/* ------------------------------------------------------------------ *
 *  The full audit log.
 *
 *  76 findings from one read-through of every product surface, captured
 *  2026-07-25. Severity is the auditor's, and the wording is theirs,
 *  with em dashes normalised out per the house style rule.
 *
 *  `verified` means the claim was independently re-checked against the
 *  source or recomputed, not just reported. Everything in the chrome
 *  group was verified by hand (contrast ratios recomputed, counts
 *  re-grepped). The rest is marked honestly.
 * ------------------------------------------------------------------ */

export type Severity = "looks-broken" | "looks-fine-but-thoughtless" | "genuinely-good";

export type Finding = {
  id: string;
  surface: string;
  title: string;
  evidence: string;
  why: string;
  idea: string;
  severity: Severity;
  verified: boolean;
};

